(function(g){'use strict';
const W=120,H=80,scale=.1;
function random(seed){let s=seed>>>0;return()=>{s=(1664525*s+1013904223)>>>0;return s/4294967296;};}
function clip(theta,rho){const t=theta*Math.PI/180,c=Math.cos(t),s=Math.sin(t),a=[];for(const x of[0,W-1])if(Math.abs(s)>.001){const y=(rho-x*c)/s;if(y>=0&&y<H)a.push([x,y]);}for(const y of[0,H-1])if(Math.abs(c)>.001){const x=(rho-y*s)/c;if(x>=0&&x<W)a.push([x,y]);}return a.length>=2?[a[0],a[a.length-1]]:null;}
function generate(seed,noise,contrast){const r=random(seed),pixels=Array(W*H).fill(0).map(()=>.72+(r()-.5)*noise),lines=[{theta:25,rho:43},{theta:25,rho:72},{theta:110,rho:14},{theta:110,rho:38}];lines.forEach(l=>{const t=l.theta*Math.PI/180;for(let y=0;y<H;y++)for(let x=0;x<W;x++)if(Math.abs(x*Math.cos(t)+y*Math.sin(t)-l.rho)<.65)pixels[y*W+x]=Math.max(0,.72-contrast+(r()-.5)*noise);});return{observations:{pixels,w:W,h:H,metresPerPixel:scale},truth:lines};}
function predict(obs,p){const mask=obs.pixels.map(v=>v<p.threshold),candidates=[];for(let theta=0;theta<180;theta+=5){const t=theta*Math.PI/180,c=Math.cos(t),s=Math.sin(t),acc=new Map();mask.forEach((on,i)=>{if(on){const rho=Math.round(((i%W)*c+Math.floor(i/W)*s)/2)*2;acc.set(rho,(acc.get(rho)||0)+1);}});for(const[rho,votes]of acc)if(votes>=p.minVotes&&clip(theta,rho))candidates.push({theta,rho,votes});}
candidates.sort((a,b)=>b.votes-a.votes);const selected=[];for(const l of candidates){if(selected.some(v=>{let d=Math.abs(v.theta-l.theta);return d<11&&Math.abs(v.rho-l.rho)<6;}))continue;const ends=clip(l.theta,l.rho),length=Math.hypot(ends[0][0]-ends[1][0],ends[0][1]-ends[1][1])*scale;selected.push({...l,ends,length,angle:(90-l.theta+180)%180});if(selected.length>=p.maxLines)break;}return{mask,lines:selected};}
function stats(lines,scanY){const rose=Array(12).fill(0);lines.forEach(l=>rose[Math.floor(l.angle/15)]++);const crossings=lines.filter(l=>(l.ends[0][1]-scanY)*(l.ends[1][1]-scanY)<=0).length;return{rose,P21:lines.reduce((s,l)=>s+l.length,0)/(W*scale*H*scale),P10:crossings/(W*scale),crossings,area_m2:W*scale*H*scale,scanLength_m:W*scale};}
function evaluate(pred,truth){let tp=0;const used=new Set();pred.forEach(p=>{const j=truth.findIndex((t,i)=>!used.has(i)&&Math.abs(p.theta-t.theta)<=10&&Math.abs(p.rho-t.rho)<=5);if(j>=0){tp++;used.add(j);}});const precision=pred.length?tp/pred.length:0,recall=tp/truth.length;return{tp,predicted:pred.length,reference:truth.length,precision,recall,f1:precision+recall?2*precision*recall/(precision+recall):0};}
function run(p={}){const params={seed:1704,noise:.12,contrast:.5,threshold:.4,minVotes:35,maxLines:8,scanY:40,...p},f=generate(params.seed,params.noise,params.contrast),prediction=predict(f.observations,params);const base=predict(f.observations,{...params,minVotes:70,maxLines:2});return{params,observations:f.observations,prediction,baseline:base,evaluationTruth:f.truth,metrics:evaluate(prediction.lines,f.truth),baselineMetrics:evaluate(base.lines,f.truth),statistics:stats(prediction.lines,params.scanY),dataSource:'固定几何参数的教学露头灰度图；4条贯穿窗口的直线裂缝，12m×8m。统计仅对当前窗口。'};}
g.G4Core={W,H,scale,generate,predict,evaluate,stats,run,clip};
})(globalThis);

